// The Marketing pack's tables (docs/marketing-plan.md §4.3; ARCHITECTURE §12.0 "Marketing"): a
// client's measured websites and what their visitors did. Same tenancy rules as the platform's
// (CLAUDE.md invariant 1): every table has tenant_id, forced RLS on app.tenant_ids, and composite
// foreign keys (site_id, tenant_id) so a row can only point at the same client's site.
//
// Migration 0035 (docs/plan.md §1.70) creates them: generated by drizzle-kit from this file, which
// the db package's drizzle config lists, plus hand-written SQL for the grants, RLS and the
// pack-ownership comments. This file imports only drizzle-orm and the platform's schema at
// runtime, so drizzle-kit can load it.
//
// Never stored, anywhere: an IP address, a user agent string, a cookie, or any identifier that
// outlives a UTC day (the salt is deleted when its day is over). A visit's times are kept to the
// hour, and a visit that reached a goal says so with no link to who the visitor is.

import { appUser, tenant } from "@countersign/db";
import { type SQL, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { BOT_REASONS, DEVICE_CLASSES, EVENT_KINDS, SOURCE_GROUPS } from "./measure/events";

export const SITE_STATUSES = ["on", "off"] as const;
export type SiteStatus = (typeof SITE_STATUSES)[number];

/** The dimensions a day's visit totals are kept by; `all` has the empty key. */
export const TOTAL_DIMENSIONS = ["all", "source", "country", "device", "entry"] as const;
export type TotalDimension = (typeof TOTAL_DIMENSIONS)[number];

/** Engaged-time bands in seconds, the last open-ended: [<10, 10–30, 30–60, 60–120, 120–240, ≥240]. */
export const ENGAGED_BAND_UPPER_SECONDS = [10, 30, 60, 120, 240] as const;
export const ENGAGED_BANDS = ENGAGED_BAND_UPPER_SECONDS.length + 1;
/** A bounce: one page, no tracked click, no goal, and less than this engaged. */
export const BOUNCE_ENGAGED_MS = 10_000;
// DECISION (Plenary Labs' retention, owner 2026-10-25, kept for Mezonas): raw events 90 days,
// visits 13 months, daily totals for good (they say nothing about any one visitor).
export const SITE_EVENT_RETENTION_DAYS = 90;
export const SITE_VISIT_RETENTION_MONTHS = 13;
/** A visit's page list is cut here: a visit that reads more is not a person reading. */
export const SITE_VISIT_MAX_PAGES = 50;
/** Events one visit may send in a day before the rest are counted as `rate` and dropped. */
export const SITE_VISIT_MAX_EVENTS = 500;

function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

const tenantId = () =>
  uuid("tenant_id")
    .notNull()
    .references(() => tenant.id);
const siteId = () => uuid("site_id").notNull();
const day = () => date("day").notNull();
const ts = (name: string) => timestamp(name, { withTimezone: true });
/** Every row of a site's data points at the same client's site. */
const siteFk = (name: string, t: { siteId: AnyPgColumn; tenantId: AnyPgColumn }) =>
  foreignKey({
    name,
    columns: [t.siteId, t.tenantId],
    foreignColumns: [site.id, site.tenantId],
  });
const pathCheck = (name: string, column: AnyPgColumn) =>
  check(name, sql`left(${column}, 1) = '/' and length(${column}) <= 512`);

/**
 * A website a client has measured: its domain (lower case, without `www.`), and the tracked
 * elements (`data-track` names) whose click counts as the visit's goal, e.g. "Talk to us".
 */
export const site = pgTable(
  "site",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    domain: text("domain").notNull(),
    name: text("name").notNull(),
    goals: text("goals").array().notNull().default(sql`'{}'::text[]`),
    status: text("status").$type<SiteStatus>().notNull().default("on"),
    createdByUserId: uuid("created_by_user_id").references(() => appUser.id),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    unique("site_id_tenant_key").on(t.id, t.tenantId),
    unique("site_domain_key").on(t.tenantId, t.domain),
    check("site_status_check", oneOf(t.status, SITE_STATUSES)),
    check(
      "site_domain_check",
      sql`${t.domain} ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' and ${t.domain} !~ '^www\\.'`,
    ),
    check("site_goals_check", sql`cardinality(${t.goals}) <= 20`),
  ],
);

/** The day's random salt for a site's visit hash. Deleted once its day is over. */
export const siteSalt = pgTable(
  "site_salt",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    salt: text("salt").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day] }),
    siteFk("site_salt_site_fk", t),
    check("site_salt_hex", sql`${t.salt} ~ '^[0-9a-f]{64}$'`),
  ],
);

/** One thing a page reported. Raw; kept 90 days. */
export const siteEvent = pgTable(
  "site_event",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    siteId: siteId(),
    at: ts("at").notNull(),
    day: day(),
    visit: text("visit").notNull(),
    viewId: uuid("view_id").notNull(),
    kind: text("kind").notNull(),
    path: text("path").notNull(),
    referrerHost: text("referrer_host"),
    referrerPath: text("referrer_path"),
    utmSource: text("utm_source"),
    utmMedium: text("utm_medium"),
    utmCampaign: text("utm_campaign"),
    utmContent: text("utm_content"),
    sourceGroup: text("source_group"),
    sourceName: text("source_name"),
    country: text("country"),
    region: text("region"),
    city: text("city"),
    timeZone: text("time_zone"),
    device: text("device"),
    browser: text("browser"),
    os: text("os"),
    language: text("language"),
    engagedMs: integer("engaged_ms"),
    scroll: integer("scroll"),
    target: text("target"),
    position: integer("position"),
    form: text("form"),
  },
  (t) => [
    siteFk("site_event_site_fk", t),
    check("site_event_kind", oneOf(t.kind, EVENT_KINDS)),
    pathCheck("site_event_path", t.path),
    check("site_event_visit_hex", sql`${t.visit} ~ '^[0-9a-f]{32}$'`),
    check(
      "site_event_source_group",
      sql`${t.sourceGroup} is null or ${oneOf(t.sourceGroup, SOURCE_GROUPS)}`,
    ),
    check("site_event_device", sql`${t.device} is null or ${oneOf(t.device, DEVICE_CLASSES)}`),
    check("site_event_country", sql`${t.country} is null or ${t.country} ~ '^[A-Z]{2}$'`),
    check(
      "site_event_ranges",
      sql`(${t.engagedMs} is null or ${t.engagedMs} between 0 and 3600000)
        and (${t.scroll} is null or ${t.scroll} between 0 and 4)
        and (${t.position} is null or ${t.position} between 0 and 100)`,
    ),
    check(
      "site_event_kind_fields",
      sql`case ${t.kind}
        when 'view' then ${t.sourceGroup} is not null and ${t.device} is not null
        when 'engage' then ${t.engagedMs} is not null and ${t.scroll} is not null
        when 'click' then ${t.target} is not null and ${t.position} is not null
        when 'form_seen' then ${t.form} is not null
        else false end`,
    ),
    index("site_event_visit_idx").on(t.tenantId, t.siteId, t.day, t.visit),
  ],
);

/** One visit (one browser, one UTC day), built nightly from its events. Kept 13 months. */
export const siteVisit = pgTable(
  "site_visit",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    visit: text("visit").notNull(),
    /** To the hour: enough for the hours of the week, too coarse to set beside anything else. */
    startedAt: ts("started_at").notNull(),
    endedAt: ts("ended_at").notNull(),
    entryPath: text("entry_path").notNull(),
    exitPath: text("exit_path").notNull(),
    pages: text("pages").array().notNull(),
    views: integer("views").notNull(),
    clicks: integer("clicks").notNull(),
    engagedMs: integer("engaged_ms").notNull(),
    sourceGroup: text("source_group").notNull(),
    sourceName: text("source_name"),
    referrerHost: text("referrer_host"),
    utmSource: text("utm_source"),
    utmMedium: text("utm_medium"),
    utmCampaign: text("utm_campaign"),
    utmContent: text("utm_content"),
    country: text("country"),
    region: text("region"),
    city: text("city"),
    timeZone: text("time_zone"),
    device: text("device").notNull(),
    browser: text("browser"),
    os: text("os"),
    language: text("language"),
    sawForm: boolean("saw_form").notNull(),
    /** A click on one of the site's goals (e.g. "Talk to us"); `goal` is the first one's name. */
    reachedGoal: boolean("reached_goal").notNull(),
    goal: text("goal"),
    bounced: boolean("bounced").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.visit] }),
    siteFk("site_visit_site_fk", t),
    check(
      "site_visit_hours",
      sql`date_trunc('hour', ${t.startedAt}, 'UTC') = ${t.startedAt}
      and date_trunc('hour', ${t.endedAt}, 'UTC') = ${t.endedAt}`,
    ),
    check("site_visit_goal", sql`${t.reachedGoal} = (${t.goal} is not null)`),
    index("site_visit_tenant_idx").on(t.tenantId, t.siteId, t.day),
  ],
);

/** Each page's day: views, entries, exits, goals, engaged time and how far down readers got. */
export const siteDailyPage = pgTable(
  "site_daily_page",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    path: text("path").notNull(),
    views: integer("views").notNull(),
    entries: integer("entries").notNull(),
    exits: integer("exits").notNull(),
    /** Visits that entered here and reached a goal. */
    goals: integer("goals").notNull(),
    formSeen: integer("form_seen").notNull(),
    engagedMs: bigint("engaged_ms", { mode: "number" }).notNull(),
    engagedBands: integer("engaged_bands").array().notNull(),
    /** Views that reached each quarter of the page: [25%, 50%, 75%, 100%]. */
    scrollReached: integer("scroll_reached").array().notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.path] }),
    siteFk("site_daily_page_site_fk", t),
    pathCheck("site_daily_page_path", t.path),
    check(
      "site_daily_page_arrays",
      sql`cardinality(${t.engagedBands}) = ${sql.raw(String(ENGAGED_BANDS))} and cardinality(${t.scrollReached}) = 4`,
    ),
  ],
);

/** Each tracked element's day: clicks, and the median position on the page (% of its height). */
export const siteDailyClick = pgTable(
  "site_daily_click",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    path: text("path").notNull(),
    target: text("target").notNull(),
    clicks: integer("clicks").notNull(),
    position: integer("position").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.path, t.target] }),
    siteFk("site_daily_click_site_fk", t),
    pathCheck("site_daily_click_path", t.path),
    check("site_daily_click_counts", sql`${t.clicks} >= 1 and ${t.position} between 0 and 100`),
  ],
);

/** A day's visit totals, overall and by one dimension at a time. */
export const siteDailyTotal = pgTable(
  "site_daily_total",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    dimension: text("dimension").$type<TotalDimension>().notNull(),
    key: text("key").notNull(),
    visits: integer("visits").notNull(),
    views: integer("views").notNull(),
    goals: integer("goals").notNull(),
    bounces: integer("bounces").notNull(),
    engagedMs: bigint("engaged_ms", { mode: "number" }).notNull(),
    engagedBands: integer("engaged_bands").array().notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.dimension, t.key] }),
    siteFk("site_daily_total_site_fk", t),
    check("site_daily_total_dimension", oneOf(t.dimension, TOTAL_DIMENSIONS)),
    check(
      "site_daily_total_key",
      sql`(${t.dimension} = 'all') = (${t.key} = '') and length(${t.key}) <= 512`,
    ),
    check(
      "site_daily_total_bands",
      sql`cardinality(${t.engagedBands}) = ${sql.raw(String(ENGAGED_BANDS))}`,
    ),
  ],
);

/** Requests not counted as visits, per day and reason. */
export const siteBotDaily = pgTable(
  "site_bot_daily",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    reason: text("reason").notNull(),
    requests: integer("requests").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.reason] }),
    siteFk("site_bot_daily_site_fk", t),
    check("site_bot_daily_reason", oneOf(t.reason, BOT_REASONS)),
    check("site_bot_daily_requests", sql`${t.requests} >= 0`),
  ],
);

/** The pack's tables, for the migration's RLS block and the pack's schema test. */
export const MARKETING_TABLES = [
  "site",
  "site_salt",
  "site_event",
  "site_visit",
  "site_daily_page",
  "site_daily_click",
  "site_daily_total",
  "site_bot_daily",
] as const;
export type MarketingTable = (typeof MARKETING_TABLES)[number];
